let TUNNEL_TIMES: [(Int, String)] = [(15, "15 minutos"), (30, "30 minutos"), (60, "1 hora"), (120, "2 horas"), (180, "3 horas"),
                                     (240, "4 horas"), (360, "6 horas"), (480, "8 horas"), (720, "12 horas")]
